/**
 * Simple Push Collision Response
 *
 * Default collision response model that simply pushes bodies apart
 * based on penetration depth. No velocity modification.
 *
 * Good for: crowds, stress tests, simple interactions
 *
 * ```js
 * import { collisionResponseRegistry, SimplePushResponse } from '@three-blocks/pro';
 *
 * collisionResponseRegistry.register( SimplePushResponse );
 * collisionResponseRegistry.setActiveModel( 'simple-push' );
 * ```
 *
 * @module @three-blocks/pro/physics/models/responses/SimplePushResponse
 * @short Simple position-only collision response.
 * @category Physics
 * @tags Collision, Response, Simple
 */
/**
 * Simple push collision response - position correction only.
 *
 * Bodies are pushed apart equally by half the penetration depth.
 * No velocity changes, no momentum transfer.
 *
 * @type {CollisionResponseModel}
 */
export const SimplePushResponse: CollisionResponseModel;
